static readonly ConcurrentDictionary<Guid, TaskCompletionSource<Reply>> Pending = new();
async Task<Reply> CallAsync(Request request, CancellationToken ct)
{
    var id = Guid.NewGuid();
    var tcs = new TaskCompletionSource<Reply>(
        TaskCreationOptions.RunContinuationsAsynchronously);
    Pending[id] = tcs;
    try {
        await transport.SendAsync(new Envelope(id, request), ct);
        return await tcs.Task.WaitAsync(TimeSpan.FromSeconds(5), ct);
    }
    finally { Pending.TryRemove(id, out _); }   // abandon on timeout/cancel
}

