public class OrderController(IRequestClient<CheckOrderStatus> client) : ControllerBase
{
    [HttpGet("{id}")]
    public async Task<IActionResult> Get(string id, CancellationToken ct)
    {
        var response = await client.GetResponse<OrderStatusResult>(new { id }, ct);
        return Ok(response.Message);
    }
}
